    /// Lessons generated from the knowledge base: one per plant illness, plus this month's jobs and leaf hunger signs.
    static let knowledgeLessons: [CareGuide] = {
        let k = Knowledge.shared
        var out = k.diseases.map { d in
            lesson("disease-\(d.id)", Grammar.pt(String(localized: "Understanding \(d.name.lowercased())", comment: "Lesson title about a plant illness, name in lowercase")), Grammar.pt(String(localized: "Spot it, fix it, prevent it", comment: "Care guide subtitle; short")), "cross.case.fill", Jungle.terracotta, 3, .medium,
                   when: Grammar.pt(String(localized: "If you notice: \(d.signs.prefix(1).lowercased() + d.signs.dropFirst())", comment: "When to read an illness lesson; followed by symptoms")), logs: .treat, [
                S(title: Grammar.pt(String(localized: "What you'll see", comment: "Care guide step title; short")), detail: d.signs, symbol: "eye.fill"),
                S(title: Grammar.pt(String(localized: "Why it happens", comment: "Care guide step title; short")), detail: d.why, symbol: "questionmark.circle.fill"),
                S(title: Grammar.pt(String(localized: "What helps", comment: "Care guide step title; short")), detail: d.fix, symbol: "cross.case.fill"),
                S(title: Grammar.pt(String(localized: "Next time", comment: "Care guide step title; short")), detail: d.prevent, symbol: "shield.fill"),
            ])
        }
        let topicLook: [String: (String, Color)] = [
            "propagation": ("scissors", Jungle.leaf), "watering": ("drop.fill", Jungle.sky), "light": ("sun.max.fill", gold),
            "environment": ("humidity.fill", Jungle.sky), "care": ("leaf.fill", Jungle.leaf), "safety": ("pawprint.fill", Jungle.terracotta),
            "edible": ("leaf.arrow.circlepath", Jungle.leaf), "myths": ("sparkles", plum), "flowering": ("camera.macro", plum),
            "outdoor": ("sun.horizon.fill", gold), "pests": ("ant.fill", Jungle.terracotta), "problems": ("stethoscope", Jungle.terracotta),
        ]
        out += k.topics.map { t in
            let look = topicLook[t.kind] ?? ("leaf.fill", Jungle.leaf)
            return lesson("topic-\(t.id)", t.title, t.intro.components(separatedBy: ". ").first ?? t.intro, look.0, look.1, max(2, t.steps.count / 2 + 1),
                          when: t.intro, t.steps.map { S(title: $0.title, detail: $0.detail, symbol: look.0) })
        }
        if !k.crops.isEmpty {
            let quick = k.crops.filter { $0.potLitres <= 5 }
            out.append(lesson("grow-food-pots", Grammar.pt(String(localized: "Grow food in small pots", comment: "Care guide title; short")), Grammar.pt(String(localized: "Herbs and salads for a sunny sill", comment: "Care guide subtitle; short")), "leaf.arrow.circlepath", Jungle.leaf, 4,
                              when: Grammar.pt(String(localized: "Spring to late summer, or any time on a warm windowsill.", comment: "When to do this care guide")), quick.prefix(10).map {
                S(title: $0.name, detail: Grammar.pt(String(localized: "\($0.start) Harvest in about \($0.harvestDays) days. \($0.tip)", comment: "Crop step: how to start, days to harvest, tip")), symbol: "leaf.fill")
            }))
            let big = k.crops.filter { $0.potLitres > 5 }
            out.append(lesson("grow-food-balcony", Grammar.pt(String(localized: "A balcony kitchen garden", comment: "Care guide title; short")), Grammar.pt(String(localized: "Tomatoes, beans, berries and more", comment: "Care guide subtitle; short")), "sun.max.fill", gold, 5,
                              when: Grammar.pt(String(localized: "Plan in late winter, plant out after your last frost.", comment: "When to do this care guide")), big.prefix(12).map {
                S(title: $0.name, detail: Grammar.pt(String(localized: "\($0.sun.capitalized). Pot \(Measurement(value: Double($0.potLitres), unit: UnitVolume.liters).formatted(.measurement(width: .abbreviated))). \($0.start) \($0.tip)", comment: "Crop step: sun need, pot volume, how to start, tip")), symbol: "sun.max.fill")
            }))
        }
        if !k.remedies.isEmpty {
            out.append(lesson("home-remedies", Grammar.pt(String(localized: "Gentle pest remedies", comment: "Care guide title; short")), Grammar.pt(String(localized: "Exact mixes from your kitchen cupboard", comment: "Care guide subtitle; short")), "ant.fill", Jungle.terracotta, 4, .medium,
                              when: Grammar.pt(String(localized: "At the first sign of bugs.", comment: "When to do this care guide")), logs: .treat, k.remedies.map {
                S(title: $0.name, detail: Grammar.pt(String(localized: "For \($0.forWhat). \($0.recipe) \($0.how) \($0.caution)", comment: "Home remedy step: target pests, recipe, how to use, caution")), symbol: "drop.fill")
            }))
        }
        if !k.families.isEmpty {
            out.append(lesson("plant-families", Grammar.pt(String(localized: "Plant families, and why they matter", comment: "Care guide title; short")), Grammar.pt(String(localized: "Relatives share care and quirks", comment: "Care guide subtitle; short")), "tree", plum, 4,
