                S(title: "\($0.name) · \($0.common)", detail: Grammar.pt(String(localized: "\($0.traits) \($0.care) e.g. \($0.examples.prefix(4).formatted(.list(type: .and)))." , comment: "Plant family step: traits, care, example plants")), symbol: "leaf.fill")
            }))
        }
        if !k.deficiencies.isEmpty {
            out.append(lesson("hunger-signs", Grammar.pt(String(localized: "When leaves are hungry", comment: "Care guide title; short")), Grammar.pt(String(localized: "Reading nutrient shortages", comment: "Care guide subtitle; short")), "leaf.fill", Jungle.leaf, 4,
                              when: Grammar.pt(String(localized: "Pale, patchy or oddly coloured leaves in the growing season.", comment: "When to do this care guide")), k.deficiencies.map {
                S(title: $0.name, detail: "\($0.signs) \($0.fix)", symbol: "leaf.fill")
            }))
        }
        if let m = k.month() {
            out.append(lesson("this-month", Grammar.pt(String(localized: "This month in your jungle", comment: "Care guide title; short")), Grammar.pt(String(localized: "Seasonal jobs, little and often", comment: "Care guide subtitle; short")), "calendar", gold, 2, when: Grammar.pt(String(localized: "Any day this month.", comment: "When to do this care guide")), [
