            ]))
        }
        if !k.glossary.isEmpty {
            let pick = k.glossary.shuffled().prefix(5)
            out.append(lesson("words", Grammar.pt(String(localized: "Plant words, gently explained", comment: "Care guide title; short")), Grammar.pt(String(localized: "Five terms you'll hear", comment: "Care guide subtitle; short")), "text.book.closed.fill", plum, 2, when: Grammar.pt(String(localized: "A cosy read with a cup of tea.", comment: "When to read this lesson")),
